from pathlib import Path
import json,hashlib,csv
A=Path(__file__).resolve().parents[1]
def read(p):return json.loads((A/p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert read('results/INPUT_CAP_DETAIL_VALIDATE.json')['ok'] and read('results/INPUT_CAP_NEW30_FULL_VALIDATE.json')['ok'] and read('results/INPUT_CAP_CONTEXT_NO_SELF_VALIDATE.json')['ok']
images=['review/input_cap_detail_20260909T043518Z.png','review/input_cap_integration_20260909T044155Z.png','review/input_cap_context_corridor_20260909T044306Z.png','review/input_cap_chb_detail_20260909T044432Z.png']
assert all((A/p).exists() for p in images)
out=dict(schema='WP10_C203_VISUAL_AND_VALIDATION_REVIEW_V1',reviewer='root via view_image tool',images_inspected=True,inspected_images_sha256={p:sha(A/p) for p in images},detail_image=images[0],context_image=images[-1],detail_view_instances=29,context_file_instances=37,context_published_visible_instances=30,context_hidden_for_visibility=['upper_equipment_deck_B','radiator_spreader','equipment_battery','adapter_battery','equipment_adcs_propulsion_allocation','adapter_adcs_propulsion_allocation','lower_equipment_deck_B'],context_hidden_entities_remain_in_source_plan_and_exact_checks=True,findings=['29-instance view shows split hoops, nominal liners, terminal board and outboard deck screw heads without visible embedment','Deck omitted in detail, so nut/washer gap reserves actual deck thickness','Original37-context screenshots obstruct the capacitor; published view deliberately shows only C203 fixture and CHB for clarity','CHB input pin tips visible; no actual wire connection or capacitor lead shape represented'],validation=dict(new29_detail_full=True,new29_plus_modified_deck_full_self_intersection=True,all37_topology_closed_positive_volume=True,all37_background_self_intersection=False,background_self_intersection_stop_reason='Owned 1400MiB combined working-set guard; process stopped, idle memory reclaimed, bounded checks passed'),source_bindings={p:sha(A/p) for p in ['mechanical/INPUT_CAP_MOUNT_INSTANCE_PLAN.json','mechanical/input_cap_detail.step','mechanical/input_cap_integration.step','results/INPUT_CAP_NEW30_FULL_VALIDATE.json','results/INPUT_CAP_CONTEXT_NO_SELF_VALIDATE.json','results/INPUT_CAP_VIEW_VALIDATION.json']},whole_design_complete=False)
(A/'results/INPUT_CAP_VISUAL_REVIEW.json').write_text(json.dumps(out,indent=2),encoding='utf-8')
D=A.parent;parent=list(csv.DictReader((D/'results/OUTPUT_SHA256.csv').open(encoding='utf-8-sig')));bad=[r['path'] for r in parent if not (D/r['path']).exists() or sha(D/r['path'])!=r['sha256']];assert not bad,bad
(A/'results/PARENT_INTEGRITY.json').write_text(json.dumps(dict(count=len(parent),mismatches=bad,all_parent_indexed_bytes_unchanged=True,current_verifier='tools/record_input_cap_visual.py'),indent=2),encoding='utf-8')
print(json.dumps(dict(images_inspected=len(images),parent_files_unchanged=len(parent),new30_full_validation=True,whole_background_self_intersection=False)))
